package com.lanse.fish;

import android.content.Context;
import org.json.*;
import java.io.*;
import java.util.*;

/**
 * The single source of truth for the original 13 categories / 106 animations.
 *
 * The old implementation merged categories in the asset pipeline (日常/互动/吃饭)
 * and picked a new animation from a 30-second timer. Both are gone: the catalog
 * keeps the original classification, exposes the visible bounds generated by
 * scripts/prepare_assets.py, and lets each pet own its own shuffle bag/history.
 */
public final class AnimationCatalog {
    public record Motion(String id, String name, String category, String file,
                         float x0, float y0, float x1, float y1) {}

    /** Display order matches the original dsh-pet menu / README. */
    public static final String[] CATEGORY_ORDER = {
        "待机", "转向", "拖拽", "点击回应", "移动", "小动作", "玩耍",
        "吃什么", "时节", "文字", "余额档位", "碎碎念", "工作状态"
    };
    private static final Set<String> AUTO_CATEGORIES = new HashSet<>(Arrays.asList(
        "待机", "转向", "移动", "小动作", "玩耍", "吃什么", "时节", "文字"
    ));
    private static final String[] CLICK_IDS = {
        "点击回应-开心跃动", "点击回应-害羞惊讶", "点击回应-傲娇生气",
        "点击回应-挠痒咯咯笑", "点击回应-元气挥手"
    };

    public final List<Motion> motions = new ArrayList<>();
    public final JSONObject config;
    private final LinkedHashMap<String, List<Motion>> groups = new LinkedHashMap<>();
    private final List<Motion> autoPool = new ArrayList<>();
    private final List<Motion> clickPool = new ArrayList<>();
    private final List<Motion> movePool = new ArrayList<>();

    public AnimationCatalog(Context c) throws Exception {
        JSONObject catalog = new JSONObject(read(c, "catalog.json"));
        JSONArray list = catalog.getJSONArray("animations");
        for (int i = 0; i < list.length(); i++) {
            JSONObject o = list.getJSONObject(i);
            float x0 = 0f, y0 = 0f, x1 = 1f, y1 = 1f;
            JSONArray v = o.optJSONArray("visual");
            if (v != null && v.length() >= 4) {
                x0 = (float) v.optDouble(0, 0);
                y0 = (float) v.optDouble(1, 0);
                x1 = (float) v.optDouble(2, 1);
                y1 = (float) v.optDouble(3, 1);
                // Guard against a broken metadata row: keep the pet visible.
                if (x1 <= x0 || y1 <= y0) { x0 = 0f; y0 = 0f; x1 = 1f; y1 = 1f; }
            }
            motions.add(new Motion(
                o.getString("id"), o.getString("name"), o.getString("category"),
                o.getString("file"), x0, y0, x1, y1
            ));
        }
        config = new JSONObject(read(c, "original-config.json"));
        for (String cat : CATEGORY_ORDER) groups.put(cat, new ArrayList<>());
        for (Motion m : motions) groups.computeIfAbsent(m.category(), k -> new ArrayList<>()).add(m);
        for (Motion m : motions) {
            if (AUTO_CATEGORIES.contains(m.category())) autoPool.add(m);
            if ("点击回应".equals(m.category())) clickPool.add(m);
            if ("移动".equals(m.category())) movePool.add(m);
        }
    }

    public static String read(Context c, String path) throws IOException {
        try (InputStream in = c.getAssets().open(path)) {
            return PetApi.readLimited(in);
        }
    }

    public List<String> categories() {
        ArrayList<String> out = new ArrayList<>();
        for (Map.Entry<String, List<Motion>> e : groups.entrySet()) {
            if (!e.getValue().isEmpty()) out.add(e.getKey());
        }
        return out;
    }

    public List<Motion> byCategory(String category) {
        List<Motion> list = groups.get(category);
        return list == null ? Collections.emptyList() : list;
    }

    public Motion find(String name) {
        for (Motion m : motions) if (m.id().equals(name) || m.name().equals(name)) return m;
        return motions.isEmpty() ? null : motions.get(0);
    }

    public Motion match(String fragment) {
        for (Motion m : motions) if (m.name().contains(fragment)) return m;
        return motions.isEmpty() ? null : motions.get(0);
    }

    /** 85 local "ordinary" clips: idle/turn/move + 小动作/玩耍/吃什么/时节/文字. */
    public List<Motion> autoPool() {
        return Collections.unmodifiableList(autoPool);
    }

    public List<Motion> clickPool() {
        return Collections.unmodifiableList(clickPool);
    }

    public List<Motion> movePool() {
        return Collections.unmodifiableList(movePool);
    }

    /**
     * Pick the next ordinary animation from the per-pet shuffle bag.
     * A full bag always contains all 85 clips, so a complete cycle covers the
     * whole pool; recent ids add a second guard against immediate repeats.
     */
    public Motion nextAuto(Random random, Deque<String> recent, String currentId, Deque<Motion> bag) {
        if (bag == null || bag.isEmpty()) {
            ArrayList<Motion> pool = new ArrayList<>(autoPool);
            Collections.shuffle(pool, random);
            if (bag != null) bag.addAll(pool);
            else return firstDifferent(pool, currentId);
        }
        Motion pick = null;
        for (Motion m : bag) {
            if (!m.id().equals(currentId) && !recent.contains(m.id())) { pick = m; break; }
        }
        if (pick == null) {
            for (Motion m : bag) {
                if (!m.id().equals(currentId)) { pick = m; break; }
            }
        }
        if (pick == null && !bag.isEmpty()) pick = bag.peekFirst();
        if (pick != null) bag.remove(pick);
        return pick != null ? pick : motions.get(0);
    }

    /** Random action from a category, avoiding the current clip when possible. */
    public Motion nextInCategory(String category, Random random, String currentId) {
        List<Motion> list = byCategory(category);
        if (list.isEmpty()) return motions.get(0);
        ArrayList<Motion> pool = new ArrayList<>(list);
        Collections.shuffle(pool, random);
        return firstDifferent(pool, currentId);
    }

    /** Five original click responses, no hard-coded four-item subset. */
    public Motion nextClick(Random random, String currentId) {
        ArrayList<Motion> pool = new ArrayList<>(clickPool);
        Collections.shuffle(pool, random);
        return firstDifferent(pool, currentId);
    }

    public Motion workMotion(String state) {
        String name = switch (state) {
            case "thinking" -> "工作状态-思考冒泡";
            case "working" -> "工作状态-忙碌点按";
            case "result" -> "工作状态-清点归档";
            case "waiting" -> "工作状态-原地踱步张望";
            case "success" -> "工作状态-雀跃庆祝";
            case "error" -> "工作状态-垂头叹气冒汗";
            default -> "待机呼吸休闲";
        };
        return find(name);
    }

    public Motion random(Random random) {
        if (motions.isEmpty()) return null;
        return motions.get(random.nextInt(motions.size()));
    }

    private static Motion firstDifferent(List<Motion> pool, String currentId) {
        for (Motion m : pool) if (!m.id().equals(currentId)) return m;
        return pool.isEmpty() ? null : pool.get(0);
    }
}
